import re


_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*))*))?$"
)


def _parse_version(value):
    if not isinstance(value, str):
        raise ValueError("version must be a string")

    match = _VERSION_RE.fullmatch(value)
    if match is None:
        raise ValueError(f"invalid version: {value!r}")

    major, minor, patch, prerelease = match.groups()
    prerelease_ids = prerelease.split(".") if prerelease is not None else None
    return (int(major), int(minor), int(patch), prerelease_ids)


def _compare_prerelease_ids(left, right):
    for left_id, right_id in zip(left, right):
        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()

        if left_numeric and right_numeric:
            left_val = int(left_id)
            right_val = int(right_id)
            if left_val != right_val:
                return -1 if left_val < right_val else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        else:
            if left_id != right_id:
                return -1 if left_id < right_id else 1

    if len(left) != len(right):
        return -1 if len(left) < len(right) else 1
    return 0


def _compare_versions(left, right):
    left_major, left_minor, left_patch, left_pre = left
    right_major, right_minor, right_patch, right_pre = right

    for left_part, right_part in (
        (left_major, right_major),
        (left_minor, right_minor),
        (left_patch, right_patch),
    ):
        if left_part != right_part:
            return -1 if left_part < right_part else 1

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    return _compare_prerelease_ids(left_pre, right_pre)


def _parse_comparator(token):
    if token.startswith(">="):
        op, version_text = ">=", token[2:]
    elif token.startswith("<="):
        op, version_text = "<=", token[2:]
    elif token.startswith(">"):
        op, version_text = ">", token[1:]
    elif token.startswith("<"):
        op, version_text = "<", token[1:]
    elif token.startswith("="):
        op, version_text = "=", token[1:]
    elif token.startswith("^"):
        op, version_text = "^", token[1:]
    elif token.startswith("~"):
        op, version_text = "~", token[1:]
    else:
        op, version_text = "=", token

    version = _parse_version(version_text)
    return op, version


def _parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError("range must be a string")

    if not rng.strip():
        raise ValueError("invalid range: empty range")

    sets = []
    for part in re.split(r"\s*\|\|\s*", rng):
        tokens = part.split()
        if not tokens:
            raise ValueError("invalid range: empty comparator set")

        comparators = [_parse_comparator(token) for token in tokens]
        sets.append(comparators)

    return sets


def _upper_bound_for_caret(version):
    major, minor, patch, _ = version
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _upper_bound_for_tilde(version):
    major, minor, _patch, _pre = version
    return (major, minor + 1, 0, None)


def _comparator_satisfies(version, comparator):
    op, target = comparator

    if op == "=":
        return _compare_versions(version, target) == 0
    if op == ">":
        return _compare_versions(version, target) > 0
    if op == ">=":
        return _compare_versions(version, target) >= 0
    if op == "<":
        return _compare_versions(version, target) < 0
    if op == "<=":
        return _compare_versions(version, target) <= 0
    if op == "^":
        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, _upper_bound_for_caret(target)) < 0
        )
    if op == "~":
        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, _upper_bound_for_tilde(target)) < 0
        )

    raise ValueError(f"unknown comparator operator: {op!r}")


def _set_satisfies(version, comparators):
    if not all(_comparator_satisfies(version, comparator) for comparator in comparators):
        return False

    major, minor, patch, prerelease = version
    if prerelease is None:
        return True

    for _op, target in comparators:
        target_major, target_minor, target_patch, target_prerelease = target
        if (
            (major, minor, patch) == (target_major, target_minor, target_patch)
            and target_prerelease is not None
        ):
            return True

    return False


def satisfies(version, rng):
    parsed_version = _parse_version(version)
    parsed_range = _parse_range(rng)

    return any(_set_satisfies(parsed_version, comparator_set) for comparator_set in parsed_range)

