from datetime import datetime, timedelta


def _parse_field(field, min_value, max_value, normalize=None):
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item in cron field")

        if "/" in item:
            base, step_text = item.split("/", 1)
            if not step_text or not all(ch in "0123456789" for ch in step_text):
                raise ValueError("invalid step in cron field")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
        else:
            base = item
            step = 1

        if base == "*":
            start = min_value
            end = max_value
        elif "-" in base:
            parts = base.split("-", 1)
            if len(parts) != 2:
                raise ValueError("invalid range in cron field")
            left, right = parts
            if not left or not right or not all(ch in "0123456789" for ch in left + right):
                raise ValueError("invalid range in cron field")
            start = int(left)
            end = int(right)
            if start > end:
                raise ValueError("range start must be <= range end")
        else:
            if not all(ch in "0123456789" for ch in base):
                raise ValueError("invalid value in cron field")
            start = int(base)
            end = max_value if step != 1 else start

        if start < min_value or start > max_value or end < min_value or end > max_value:
            raise ValueError("value out of range in cron field")

        for value in range(start, end + 1, step):
            if normalize is not None:
                value = normalize(value)
            values.add(value)

    return values


def _normalize_dow(value):
    return 0 if value == 7 else value


def _cron_dow_for_date(date):
    return (date.weekday() + 1) % 7


def next_fire(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    doms = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    dows = _parse_field(dow_field, 0, 7, normalize=_normalize_dow)

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current_date = start.date()
    last_date = limit.date()

    while current_date <= last_date:
        if current_date.month in months:
            dom_match = current_date.day in doms
            dow_match = _cron_dow_for_date(current_date) in dows

            if dom_restricted and dow_restricted:
                day_matches = dom_match or dow_match
            else:
                day_matches = dom_match and dow_match

            if day_matches:
                for hour in sorted_hours:
                    if current_date == start.date() and hour < start.hour:
                        continue

                    for minute in sorted_minutes:
                        if (
                            current_date == start.date()
                            and hour == start.hour
                            and minute < start.minute
                        ):
                            continue

                        candidate = datetime(
                            current_date.year,
                            current_date.month,
                            current_date.day,
                            hour,
                            minute,
                        )

                        if candidate <= limit:
                            return candidate

                        raise ValueError("no match within 3000 days")

        current_date += timedelta(days=1)

    raise ValueError("no match within 3000 days")

