import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    if not isinstance(ops, list):
        raise PatchError("ops must be a list")

    current = copy.deepcopy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError("each operation must be a dict")

        op_name = op.get("op")
        if op_name not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError("unknown or missing op")

        if "path" not in op or not isinstance(op["path"], str):
            raise PatchError("missing or invalid path")

        path = _parse_pointer(op["path"])

        if op_name in {"add", "replace", "test"}:
            if "value" not in op:
                raise PatchError("missing value")
            value = op["value"]
        else:
            value = None

        if op_name in {"move", "copy"}:
            if "from" not in op or not isinstance(op["from"], str):
                raise PatchError("missing or invalid from")
            from_path = _parse_pointer(op["from"])
        else:
            from_path = None

        if op_name == "add":
            current = _add(current, path, copy.deepcopy(value))
        elif op_name == "remove":
            current = _remove(current, path)
        elif op_name == "replace":
            current = _replace(current, path, copy.deepcopy(value))
        elif op_name == "move":
            current = _move(current, from_path, path)
        elif op_name == "copy":
            current = _copy(current, from_path, path)
        elif op_name == "test":
            target = _get(current, path, must_exist=True)
            if not _json_equal(target, value):
                raise PatchError("test failed")

    return current


def _parse_pointer(pointer):
    if pointer == "":
        return []

    if not pointer.startswith("/"):
        raise PatchError("invalid pointer")

    return [_unescape_token(token) for token in pointer[1:].split("/")]


def _unescape_token(token):
    out = []
    i = 0
    while i < len(token):
        ch = token[i]
        if ch == "~":
            if i + 1 >= len(token):
                raise PatchError("invalid escape")
            nxt = token[i + 1]
            if nxt == "0":
                out.append("~")
            elif nxt == "1":
                out.append("/")
            else:
                raise PatchError("invalid escape")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def _is_proper_descendant(ancestor, descendant):
    if len(descendant) <= len(ancestor):
        return False
    return all(a == b for a, b in zip(ancestor, descendant))


def _get(doc, tokens, must_exist=False):
    node = doc
    for token in tokens:
        if isinstance(node, dict):
            if token not in node:
                if must_exist:
                    raise PatchError("target does not exist")
                return None
            node = node[token]
        elif isinstance(node, list):
            index = _parse_list_index(token)
            if index is None or index < 0 or index >= len(node):
                if must_exist:
                    raise PatchError("target does not exist")
                return None
            node = node[index]
        else:
            if must_exist:
                raise PatchError("target does not exist")
            return None
    return node


def _parse_list_index(token):
    if token == "-":
        return None
    if not token.isdigit():
        raise PatchError("invalid list index")
    if len(token) > 1 and token[0] == "0":
        raise PatchError("invalid list index")
    return int(token)


def _parent_and_key(doc, tokens, allow_dash=False):
    if not tokens:
        return None, None

    node = doc
    for token in tokens[:-1]:
        if isinstance(node, dict):
            if token not in node:
                raise PatchError("parent does not exist")
            node = node[token]
        elif isinstance(node, list):
            index = _parse_list_index(token)
            if index is None or index < 0 or index >= len(node):
                raise PatchError("parent does not exist")
            node = node[index]
        else:
            raise PatchError("parent does not exist")

    last = tokens[-1]
    if isinstance(node, dict):
        return node, last
    if isinstance(node, list):
        if allow_dash and last == "-":
            return node, len(node)
        index = _parse_list_index(last)
        if index is None:
            raise PatchError("invalid list index")
        return node, index
    raise PatchError("parent does not exist")


def _add(doc, tokens, value):
    if not tokens:
        return value

    parent, key = _parent_and_key(doc, tokens, allow_dash=True)

    if isinstance(parent, dict):
        parent[key] = value
    elif isinstance(parent, list):
        if key < 0 or key > len(parent):
            raise PatchError("invalid list index")
        parent.insert(key, value)
    else:
        raise PatchError("parent does not exist")

    return doc


def _remove(doc, tokens):
    if not tokens:
        raise PatchError("cannot remove root")

    parent, key = _parent_and_key(doc, tokens, allow_dash=False)

    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError("target does not exist")
        del parent[key]
    elif isinstance(parent, list):
        if key < 0 or key >= len(parent):
            raise PatchError("target does not exist")
        del parent[key]
    else:
        raise PatchError("parent does not exist")

    return doc


def _replace(doc, tokens, value):
    if not tokens:
        return value

    parent, key = _parent_and_key(doc, tokens, allow_dash=False)

    if isinstance(parent, dict):
        if key not in parent:
            raise PatchError("target does not exist")
        parent[key] = value
    elif isinstance(parent, list):
        if key < 0 or key >= len(parent):
            raise PatchError("target does not exist")
        parent[key] = value
    else:
        raise PatchError("parent does not exist")

    return doc


def _move(doc, from_tokens, to_tokens):
    if from_tokens == to_tokens:
        _get(doc, from_tokens, must_exist=True)
        return doc

    if _is_proper_descendant(from_tokens, to_tokens):
        raise PatchError("cannot move into itself")

    value = _get(doc, from_tokens, must_exist=True)
    doc = _remove(doc, from_tokens)
    doc = _add(doc, to_tokens, value)
    return doc


def _copy(doc, from_tokens, to_tokens):
    value = copy.deepcopy(_get(doc, from_tokens, must_exist=True))
    return _add(doc, to_tokens, value)


def _json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(_json_equal(a[key], b[key]) for key in a)

    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_json_equal(x, y) for x, y in zip(a, b))

    return a == b

