import re


_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
    r"(?:\.(?:0|[1-9]\d*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*))*))?$"
)


def _parse_version(version):
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    match = _VERSION_RE.match(version)
    if not match:
        raise ValueError(f"invalid version: {version!r}")

    major, minor, patch, prerelease = match.groups()
    prerelease_ids = prerelease.split(".") if prerelease is not None else None
    return (int(major), int(minor), int(patch), prerelease_ids)


def _is_numeric_identifier(identifier):
    return identifier.isdigit()


def _compare_identifiers(left, right):
    left_numeric = _is_numeric_identifier(left)
    right_numeric = _is_numeric_identifier(right)

    if left_numeric and right_numeric:
        left_value = int(left)
        right_value = int(right)
        if left_value < right_value:
            return -1
        if left_value > right_value:
            return 1
        return 0

    if left_numeric:
        return -1
    if right_numeric:
        return 1

    if left < right:
        return -1
    if left > right:
        return 1
    return 0


def _compare_versions(left, right):
    for index in range(3):
        if left[index] < right[index]:
            return -1
        if left[index] > right[index]:
            return 1

    left_prerelease = left[3]
    right_prerelease = right[3]

    if left_prerelease is None and right_prerelease is None:
        return 0
    if left_prerelease is None:
        return 1
    if right_prerelease is None:
        return -1

    for left_id, right_id in zip(left_prerelease, right_prerelease):
        result = _compare_identifiers(left_id, right_id)
        if result != 0:
            return result

    if len(left_prerelease) < len(right_prerelease):
        return -1
    if len(left_prerelease) > len(right_prerelease):
        return 1
    return 0


def _version_less_than(version, other):
    return _compare_versions(version, other) < 0


def _version_less_than_or_equal(version, other):
    return _compare_versions(version, other) <= 0


def _version_greater_than(version, other):
    return _compare_versions(version, other) > 0


def _version_greater_than_or_equal(version, other):
    return _compare_versions(version, other) >= 0


def _version_equals(version, other):
    return _compare_versions(version, other) == 0


def _caret_upper_bound(version):
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper_bound(version):
    major, minor = version[0], version[1]
    return (major, minor + 1, 0, None)


def _parse_comparator(token):
    if not token:
        raise ValueError("empty comparator")

    if token[0] in "=><^~":
        if token[0] in "><" and len(token) > 1 and token[1] == "=":
            operator = token[:2]
            version_text = token[2:]
        else:
            operator = token[0]
            version_text = token[1:]
    else:
        operator = "="
        version_text = token

    if not version_text:
        raise ValueError(f"invalid comparator: {token!r}")

    return operator, _parse_version(version_text)


def _parse_range(rng):
    if not isinstance(rng, str):
        raise ValueError("range must be a string")

    sets = []
    for raw_set in re.split(r"\s*\|\|\s*", rng):
        tokens = raw_set.split()
        if not tokens:
            raise ValueError(f"invalid range: {rng!r}")

        comparators = []
        for token in tokens:
            comparators.append(_parse_comparator(token))

        sets.append(comparators)

    return sets


def _set_satisfies(version, comparators):
    if version[3] is not None:
        has_matching_prerelease_comparator = False
        for _, comparator_version in comparators:
            if (
                comparator_version[3] is not None
                and version[:3] == comparator_version[:3]
            ):
                has_matching_prerelease_comparator = True
                break

        if not has_matching_prerelease_comparator:
            return False

    for operator, comparator_version in comparators:
        if operator == "=":
            if not _version_equals(version, comparator_version):
                return False
        elif operator == ">":
            if not _version_greater_than(version, comparator_version):
                return False
        elif operator == ">=":
            if not _version_greater_than_or_equal(version, comparator_version):
                return False
        elif operator == "<":
            if not _version_less_than(version, comparator_version):
                return False
        elif operator == "<=":
            if not _version_less_than_or_equal(version, comparator_version):
                return False
        elif operator == "^":
            if not _version_greater_than_or_equal(version, comparator_version):
                return False
            if not _version_less_than(version, _caret_upper_bound(comparator_version)):
                return False
        elif operator == "~":
            if not _version_greater_than_or_equal(version, comparator_version):
                return False
            if not _version_less_than(version, _tilde_upper_bound(comparator_version)):
                return False
        else:
            raise ValueError(f"unsupported comparator operator: {operator!r}")

    return True


def satisfies(version, rng):
    parsed_version = _parse_version(version)
    comparator_sets = _parse_range(rng)

    for comparators in comparator_sets:
        if _set_satisfies(parsed_version, comparators):
            return True

    return False

