from datetime import datetime, timedelta


def _is_int(value):
    return bool(value) and all(ch in "0123456789" for ch in value)


def _parse_field(field, min_value, max_value, normalize=None):
    values = set()

    for item in field.split(","):
        if not item:
            raise ValueError("empty item in cron field")

        if "/" in item:
            base, step_text = item.split("/", 1)
            if not _is_int(step_text):
                raise ValueError("invalid step in cron field")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1")
        else:
            base = item
            step = 1

        if base == "*":
            start = min_value
            end = max_value
        elif "-" in base:
            start_text, end_text = base.split("-", 1)
            if not _is_int(start_text) or not _is_int(end_text):
                raise ValueError("invalid range in cron field")
            start = int(start_text)
            end = int(end_text)
            if start > end:
                raise ValueError("range start must be <= range end")
        else:
            if not _is_int(base):
                raise ValueError("invalid value in cron field")
            start = int(base)
            end = max_value if "/" in item else start

        if start < min_value or start > max_value or end < min_value or end > max_value:
            raise ValueError("value out of range in cron field")

        for value in range(start, end + 1, step):
            if normalize is not None:
                value = normalize(value)
            values.add(value)

    return values


def _normalize_dow(value):
    return 0 if value == 7 else value


def _cron_dow(dt):
    return dt.isoweekday() % 7


def next_fire(expr, after):
    if not isinstance(expr, str):
        raise ValueError("cron expression must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    days_of_month = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12)
    days_of_week = _parse_field(dow_field, 0, 7, normalize=_normalize_dow)

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = after + timedelta(days=3000)

    current_day = start.date()
    last_day = limit.date()

    while current_day <= last_day:
        month_ok = current_day.month in months
        dom_ok = current_day.day in days_of_month
        dow_ok = _cron_dow(datetime(current_day.year, current_day.month, current_day.day)) in days_of_week

        if dom_restricted and dow_restricted:
            day_ok = dom_ok or dow_ok
        else:
            day_ok = dom_ok and dow_ok

        if month_ok and day_ok:
            start_hour = start.hour if current_day == start.date() else 0
            start_minute = start.minute if current_day == start.date() else 0

            for hour in sorted_hours:
                if current_day == start.date() and hour < start_hour:
                    continue

                for minute in sorted_minutes:
                    if current_day == start.date() and hour == start_hour and minute < start_minute:
                        continue

                    candidate = datetime(current_day.year, current_day.month, current_day.day, hour, minute)
                    if candidate > after and candidate <= limit:
                        return candidate

        current_day += timedelta(days=1)

    raise ValueError("no matching datetime within 3000 days")

