import copy


class PatchError(ValueError):
    pass


def apply_patch(doc, ops):
    """Apply a JSON Patch (RFC 6902 subset) to `doc` and return the resulting NEW document.

    `doc` and `ops` must never be modified, and the result must share no mutable object (dict/list) with either.
    The patch is all-or-nothing: on any error, raise PatchError.

    `ops` is a list of dicts. Each has "op" (one of add, remove, replace, move, copy, test) and "path";
    add/replace/test also need "value" (which may be None); move/copy also need "from". Missing keys are errors.

    Paths are JSON Pointers: "" is the whole document; otherwise "/" followed by "/"-separated tokens in which
    "~1" stands for "/" and "~0" for "~" ("~01" is the key "~1"). A "~" not followed by 0 or 1 is an error.
    A token addressing a list must be a base-10 index without leading zeros ("0" is fine). "-" means "past the
    end of the list" and is only allowed as the final token of an add (or of the target of move/copy).

    add:     object -> set the member (replacing any existing value); list -> insert BEFORE the index
             (index == len appends, index > len is an error). Adding at "" replaces the whole document.
             The parent container must exist.
    remove:  the target must exist. Removing "" is an error.
    replace: the target must exist. Replacing "" replaces the whole document.
    move:    remove the value at "from", then add it at "path". It is an error if "path" lies strictly inside
             "from" (a proper descendant). from == path is a no-op, but "from" must still exist.
    copy:    add a deep copy of the value at "from" at "path".
    test:    the target must exist and equal "value". Equality is JSON equality: numbers by value (1 == 1.0),
             booleans are never equal to numbers, objects by keys and values, lists elementwise.
    """
    if not isinstance(ops, list):
        raise PatchError("ops must be a list")

    result = copy.deepcopy(doc)

    for op in ops:
        if not isinstance(op, dict):
            raise PatchError("each operation must be a dict")

        op_name = op.get("op")
        if op_name not in {"add", "remove", "replace", "move", "copy", "test"}:
            raise PatchError("invalid or missing op")

        if "path" not in op:
            raise PatchError("missing path")
        path = op["path"]
        path_tokens = parse_pointer(path)

        if op_name in {"add", "replace", "test"} and "value" not in op:
            raise PatchError("missing value")
        if op_name in {"move", "copy"} and "from" not in op:
            raise PatchError("missing from")

        if op_name == "add":
            result = do_add(result, path_tokens, op["value"])
        elif op_name == "remove":
            result = do_remove(result, path_tokens)
        elif op_name == "replace":
            result = do_replace(result, path_tokens, op["value"])
        elif op_name == "move":
            result = do_move(result, path_tokens, op["from"])
        elif op_name == "copy":
            result = do_copy(result, path_tokens, op["from"])
        elif op_name == "test":
            do_test(result, path_tokens, op["value"])

    return result


def parse_pointer(path):
    if not isinstance(path, str):
        raise PatchError("path must be a string")

    if path == "":
        return []

    if not path.startswith("/"):
        raise PatchError("invalid path")

    tokens = []
    for raw_token in path[1:].split("/"):
        tokens.append(unescape_token(raw_token))
    return tokens


def unescape_token(token):
    for i, ch in enumerate(token):
        if ch == "~":
            if i + 1 >= len(token) or token[i + 1] not in "01":
                raise PatchError("invalid escape in path token")
    return token.replace("~1", "/").replace("~0", "~")


def parse_list_index(token, allow_dash=False):
    if token == "-":
        if not allow_dash:
            raise PatchError("'-' is only allowed as the final token of an add or move/copy target")
        return None

    if not token:
        raise PatchError("invalid list index")

    if not token.isdigit():
        raise PatchError("invalid list index")

    if len(token) > 1 and token[0] == "0":
        raise PatchError("list index must not have leading zeros")

    return int(token)


def resolve_parent(doc, tokens, op_name, allow_dash_target=False):
    if not tokens:
        raise PatchError("path must not be empty")

    current = doc
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise PatchError("parent does not exist")
            current = current[token]
        elif isinstance(current, list):
            index = parse_list_index(token, allow_dash=False)
            if index < 0 or index >= len(current):
                raise PatchError("parent does not exist")
            current = current[index]
        else:
            raise PatchError("parent is not a container")

    if not isinstance(current, (dict, list)):
        raise PatchError("parent is not a container")

    return current


def get_value(doc, tokens):
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise PatchError("target does not exist")
            current = current[token]
        elif isinstance(current, list):
            index = parse_list_index(token, allow_dash=False)
            if index < 0 or index >= len(current):
                raise PatchError("target does not exist")
            current = current[index]
        else:
            raise PatchError("target does not exist")
    return current


def do_add(doc, tokens, value):
    if not tokens:
        return copy.deepcopy(value)

    parent = resolve_parent(doc, tokens, "add", allow_dash_target=True)
    token = tokens[-1]

    if isinstance(parent, dict):
        parent[token] = copy.deepcopy(value)
    elif isinstance(parent, list):
        if token == "-":
            parent.append(copy.deepcopy(value))
        else:
            index = parse_list_index(token, allow_dash=False)
            if index < 0 or index > len(parent):
                raise PatchError("add index out of range")
            parent.insert(index, copy.deepcopy(value))
    else:
        raise PatchError("parent is not a container")

    return doc


def do_remove(doc, tokens):
    if not tokens:
        raise PatchError("cannot remove the whole document")

    parent = resolve_parent(doc, tokens, "remove")
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError("target does not exist")
        del parent[token]
    elif isinstance(parent, list):
        index = parse_list_index(token, allow_dash=False)
        if index < 0 or index >= len(parent):
            raise PatchError("target does not exist")
        parent.pop(index)
    else:
        raise PatchError("parent is not a container")

    return doc


def do_replace(doc, tokens, value):
    if not tokens:
        return copy.deepcopy(value)

    parent = resolve_parent(doc, tokens, "replace")
    token = tokens[-1]

    if isinstance(parent, dict):
        if token not in parent:
            raise PatchError("target does not exist")
        parent[token] = copy.deepcopy(value)
    elif isinstance(parent, list):
        index = parse_list_index(token, allow_dash=False)
        if index < 0 or index >= len(parent):
            raise PatchError("target does not exist")
        parent[index] = copy.deepcopy(value)
    else:
        raise PatchError("parent is not a container")

    return doc


def do_move(doc, path_tokens, from_path):
    from_tokens = parse_pointer(from_path)

    if from_tokens == path_tokens:
        get_value(doc, from_tokens)
        return doc

    if len(path_tokens) > len(from_tokens) and path_tokens[:len(from_tokens)] == from_tokens:
        raise PatchError("move target must not be a proper descendant of from")

    value = get_value(doc, from_tokens)
    doc = do_remove(doc, from_tokens)
    doc = do_add(doc, path_tokens, value)
    return doc


def do_copy(doc, path_tokens, from_path):
    from_tokens = parse_pointer(from_path)
    value = copy.deepcopy(get_value(doc, from_tokens))
    return do_add(doc, path_tokens, value)


def do_test(doc, tokens, value):
    actual = get_value(doc, tokens)
    if not json_equal(actual, value):
        raise PatchError("test failed")
    return doc


def json_equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    if isinstance(a, dict) and isinstance(b, dict):
        if set(a.keys()) != set(b.keys()):
            return False
        return all(json_equal(a[key], b[key]) for key in a)

    if isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b):
            return False
        return all(json_equal(x, y) for x, y in zip(a, b))

    return a == b

